function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // binary representation of 1023
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText('1111111111', 10, 10);
  // symbolic object: a circle with 10 segments
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2, H/2, 50, 2*i*Math.PI/10, 2*(i+1)*Math.PI/10);
    ctx.stroke();
  }
  // oscillating circle
  ctx.beginPath();
  ctx.arc(W/2 + 30*Math.sin(t), H/2, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.restore();
}
